package cn.breezeth.kaleidoscope_grilling;
import net.minecraft.network.chat.Component;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.core.registries.Registries;import net.minecraft.resources.ResourceKey;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.effect.MobEffectInstance;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.item.Item;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.TooltipFlag;import net.minecraft.world.level.Level;import java.util.List;
public final class EffectFoodItem extends Item{private final ResourceLocation effect;private final int duration;private final String tooltip;public EffectFoodItem(Properties p,ResourceLocation e,int d,String t){super(p);effect=e;duration=d;tooltip=t;}@Override public ItemStack finishUsingItem(ItemStack s,Level l,LivingEntity entity){ItemStack result=super.finishUsingItem(s,l,entity);if(!l.isClientSide)BuiltInRegistries.MOB_EFFECT.getHolder(ResourceKey.create(Registries.MOB_EFFECT,effect)).ifPresent(h->entity.addEffect(new MobEffectInstance(h,duration)));return result;}@Override public void appendHoverText(ItemStack s,TooltipContext c,List<Component>lines,TooltipFlag f){FoodTooltip.appendMaxim(lines,tooltip);FoodTooltip.appendEffect(lines,c,effect,duration);}}
